INSERT INTO library_entry (user_id, game_id, status, desire, store_id, platform, actual_hours,
  started_at, finished_at, rating, notes, steam_hours, steam_updated_at, imported, created_at, updated_at)
SELECT '00000000-0000-4000-8000-000000000001'::uuid, g.id, v.status::game_status, v.desire::desire_level, st.id, v.platform, v.actual_hours,
